var e=[{id:1,name:`Sarah Mitchell`,role:`Art Collector`,location:`New York, USA`,text:`The painting I commissioned from Suman exceeded all my expectations. He beautifully captured the spirit of the Himalayas. The colors are vibrant and the texture is mesmerizing. A true centerpiece in my living room.`,rating:5,avatar:``,service:`Landscape Commission`,date:`2024-03-15`},{id:2,name:`David & Emma Thompson`,role:`Newlyweds`,location:`London, UK`,text:`Having a live painter at our wedding in Pokhara was the highlight of the event! The artist was incredibly professional and the final piece is a beautiful, emotional snapshot of our special day. Highly recommend!`,rating:5,avatar:``,service:`Wedding Live Painting`,date:`2023-11-20`},{id:3,name:`Prakash Maharjan`,role:`Business Owner`,location:`Kathmandu, Nepal`,text:`I ordered several custom corporate gifts for our top clients. The process was seamless, and the recipients were absolutely thrilled with the unique, high-quality art pieces. Great service and communication.`,rating:5,avatar:``,service:`Corporate Gifts`,date:`2024-01-10`},{id:4,name:`Elena Rostova`,role:`Tourist`,location:`Moscow, Russia`,text:`The Trekking & Painting experience was unforgettable. Painting the Annapurna range while actually being there, guided by an expert artist, helped me connect with nature on a whole new level. Best trip ever.`,rating:5,avatar:``,service:`Trekking & Painting`,date:`2023-10-05`},{id:5,name:`Michael Chang`,role:`Art Enthusiast`,location:`Singapore`,text:`I purchased "Himalayan Dawn" from the gallery and it arrived in perfect condition. The framing is exquisite and the painting itself is breathtaking. I will definitely be a returning customer.`,rating:4,avatar:``,service:`Original Painting`,date:`2024-02-28`},{id:6,name:`Sita Gurung`,role:`Homemaker`,location:`Pokhara, Nepal`,text:`The portrait of my late father was done with so much care and respect. It brought tears to our eyes. Thank you for capturing his gentle smile so perfectly. It means the world to our family.`,rating:5,avatar:``,service:`Custom Portraits`,date:`2023-12-15`},{id:7,name:`James Wilson`,role:`Software Engineer`,location:`Sydney, Australia`,text:`Took the group workshop while visiting Nepal. It was a fun, relaxing environment. Even though I have no painting background, I managed to create a piece I am proud to hang on my wall. Excellent guidance!`,rating:5,avatar:``,service:`Group Workshop`,date:`2024-04-02`},{id:8,name:`Anita Desai`,role:`Interior Designer`,location:`Mumbai, India`,text:`I frequently source artworks from Caterpillar Art Gallery for my clients. Their collection is diverse, authentic, and reasonably priced. The team is always helpful in finding the right pieces for specific spaces.`,rating:4,avatar:``,service:`Gallery Purchase`,date:`2024-01-25`},{id:9,name:`Robert Klein`,role:`Retiree`,location:`Berlin, Germany`,text:`The pet painting of my golden retriever, Max, is so full of life! The artist really captured his goofy expression. It is a wonderful keepsake that brings me joy every day.`,rating:5,avatar:``,service:`Pet Paintings`,date:`2023-09-18`},{id:10,name:`Nima Sherpa`,role:`Trekking Guide`,location:`Namche Bazaar, Nepal`,text:`I have partnered with the gallery for their trekking and painting tours. It is amazing to see my beautiful country through the eyes of artists. The organizers are very professional and care deeply about the environment.`,rating:5,avatar:``,service:`Trekking & Painting`,date:`2023-11-30`},{id:11,name:`Sophie Laurent`,role:`Event Manager`,location:`Paris, France`,text:`Hired them for a live painting session during a corporate retreat in Pokhara. It was a huge hit! The artist was engaging and the final artwork is now proudly displayed in our headquarters.`,rating:5,avatar:``,service:`Live Painting`,date:`2024-03-05`},{id:12,name:`Karma Lama`,role:`Student`,location:`Pokhara, Nepal`,text:`The solo workshop was exactly what I needed to refine my acrylic techniques. The one-on-one attention really helped me understand color mixing and brushwork better. Great value for the price.`,rating:4,avatar:``,service:`Solo Workshop`,date:`2024-02-14`}];async function t(){try{let e=await fetch(`/api/instagram`);if(!e.ok)throw Error(`HTTP error! status: ${e.status}`);return await e.json()}catch(e){throw console.error(`Failed to fetch Instagram feed from backend:`,e),e}}export{e as n,t};